source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {value for row in grid for value in row if value != 0}
    marker = min(colors, key=lambda value: sum(row.count(value) for row in grid))

    remaining = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker}
    components = []
    while remaining:
        start = remaining.pop()
        component = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    cell = (r + dr, c + dc)
                    if cell in remaining:
                        remaining.remove(cell)
                        component.add(cell)
                        stack.append(cell)
        components.append(component)

    shape = max(components, key=len)
    top = min(r for r, c in shape)
    left = min(c for r, c in shape)
    pattern = {(r - top, c - left) for r, c in shape}
    ph = max(r for r, c in pattern) + 1
    pw = max(c for r, c in pattern) + 1

    out = [row[:] for row in grid]
    for r in range(h - ph + 1):
        for c in range(w - pw + 1):
            if all(grid[r + dr][c + dc] == 0 for dr, dc in pattern):
                for dr, dc in pattern:
                    out[r + dr][c + dc] = marker
    return out
'''
